  'plans.storageWarningUpgrade': 'Онови до Chatyy One та отримай 200 ГБ!',
  'plans.faqWhatIsPlus': 'Що таке Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'Це преміум план Chatyy, який захищає всі твої розмови, фото та відео. З Chatyy One, навіть якщо ти випадково щось видалиш, можеш відновити це протягом 30 днів. Крім того, ти отримуєш 200 ГБ пам\'яті, One AI як особистого помічника та можеш надсилати файли до 100 МБ.',
  'plans.faqCancelAnswer': 'Твій план залишиться активним до закінчення оплачуваного періоду. Після цього ти повернешся до безкоштовного плану. Твої фото та відео, які перевищують 15 ГБ, зберігатимуться ще 30 днів, щоб ти міг їх завантажити.',
  'plans.faqHowFamily': 'Як працює план Pro?',
  'plans.faqHowFamilyAnswer': 'Ти можеш додати до 4 людей з твоєї родини. Всі ділять 500 ГБ пам\'яті та отримують всі переваги Chatyy One. Кожна людина має свій приватний простір — ніхто не бачить файли інших.',
  'plans.faqChangePlanAnswer': 'Так! Якщо ти оновиш з Plus до Pro, буде стягнута лише пропорційна різниця. Якщо знизиш план, поточний залишиться до закінчення періоду.',
  'plans.faqCardDeclined': 'Мою картку відхилили, що робити?',
  'plans.faqCardDeclinedAnswer': 'У тебе є 7 днів, щоб оновити свою картку. Протягом цього періоду всі твої переваги продовжують діяти. Після 7 днів план повернеться до безкоштовного.',
  'plans.faqDataSafe': 'Мої дані в безпеці?',
